function r(){gsap.utils.toArray(".section--hero").forEach(o=>{let e=o.querySelector(".wp-block-cover__image-background");e&&gsap.effects.parallax(e,{yFrom:0,yTo:5,scaleFrom:1,scaleTo:1.04,parent:o,start:"top top"})})}function c(){gsap.utils.toArray(".section--hero-2").forEach(o=>{let e=o.querySelector(".wp-block-cover"),p=o.querySelector(".wp-block-cover__image-background");e&&p&&gsap.effects.parallax(p,{parent:e,yFrom:0,scaleFrom:1,start:"top top"})})}function s(){gsap.utils.toArray(".section--hero-3").forEach(o=>{let e=o.querySelector(".wp-block-cover__image-background");e&&gsap.effects.parallax(e,{yFrom:0,yTo:5,scaleFrom:1,scaleTo:1.04,parent:o,start:"top top"})})}function n(){gsap.utils.toArray(".section--mission").forEach(o=>{let e=o.querySelector(".wp-block-cover__image-background");e&&gsap.effects.parallax(e,{parent:o})})}function a(){gsap.utils.toArray(".section--contact").forEach(o=>{let e=o.querySelector(".wp-block-cover__image-background");e&&gsap.effects.parallax(e,{parent:o})})}function i(){if(!document.body.classList.contains("wp-singular"))return;let o=document.querySelector(".entry")?.querySelector(".wp-block-cover"),e=o?.querySelector(".wp-block-cover__image-background");e&&gsap.effects.parallax(e,{yFrom:0,yTo:5,scaleFrom:1,scaleTo:1.04,parent:o,start:"top top"})}window.addEventListener("load",()=>{r(),c(),s(),n(),a(),i()});
